#include <stdio.h>

static void swap(int *a, int *b) { int t = *a; *a = *b; *b = t; }

static void sift_down(int *a, int n, int i) {
    while (1) {
        int L = 2 * i + 1, R = 2 * i + 2, big = i;
        if (L < n && a[L] > a[big]) big = L;
        if (R < n && a[R] > a[big]) big = R;
        if (big == i) break;              /* 已满足堆序 */
        swap(&a[i], &a[big]);
        i = big;
    }
}

int main(void) {
    int a[] = {4, 10, 3, 5, 1, 8, 2};
    int n = 7;
    printf("原始数组:");
    for (int i = 0; i < n; i++) printf(" %d", a[i]);
    printf("\n");

    /* 自底向上建堆：从最后一个非叶节点 (n/2-1) 往前 sift_down，总代价 O(N) */
    for (int i = n / 2 - 1; i >= 0; i--) sift_down(a, n, i);
    printf("建成大顶堆:");
    for (int i = 0; i < n; i++) printf(" %d", a[i]);
    printf("  (堆顶 a[0]=%d)\n", a[0]);

    /* 堆排序：反复把堆顶换到末尾，再对缩小后的堆 sift_down */
    for (int end = n - 1; end > 0; end--) {
        swap(&a[0], &a[end]);
        sift_down(a, end, 0);
    }
    printf("堆排序后(升序):");
    for (int i = 0; i < n; i++) printf(" %d", a[i]);
    printf("\n");
    return 0;
}
